package com.example.survivor.game;
import java.io.Serializable;
import java.util.*;
/** Vera and Misha remain in the school; neither can join the shelter or evacuation. */
final class VeraStory implements Serializable {
 private static final long serialVersionUID=1L;
 static final String KEY="Связка ключей Веры";
 boolean appeared,fed,helped,keyTaken,cabinetOpen,cabinetLoot;int stage;Fighter misha;VeraEnemy enemy;
 void trySpawn(Random random){if(!appeared&&random.nextInt(100)<35){appeared=true;GameIO.checkpoint();}}
 boolean available(){return appeared && stage!=6 && stage!=7 && stage!=8;}
 boolean cabinetAvailable(){return appeared&&(helped || stage==7 || stage==8);}
 Fighter child(){if(misha==null){misha=new Fighter("Миша","Тяжёлая травма ноги",100);misha.storyInjury(BodyPart.LEFT_LEG,50);}return misha;}
 void note(WorldStories w,String text){w.note("Вера и Миша",text);GameIO.checkpoint();}
 boolean interact(Fighter p,WorldStories w,Scanner sc,Random random){
  while(p.isAlive() && GameIO.hasInput(sc)){
   if(stage==0){GameIO.storyMenu("Не открывай шкаф","При открытии двери слышится женский голос.\n\nВера: «Закрой дверь. Медленно».\n\nВ полутёмной комнате стоит женщина с ножом. За её спиной старый шкаф.\n\nДжон: «Я не собираюсь нападать».\n\nВера: «Тогда чего тебе надо?»\n\nДжон: «Ищу припасы».\n\nВера: «Здесь ничего нет».\n\nИз шкафа доносится приглушённый кашель. Джон поворачивает голову.\n\nВера: «Я сказала, ничего нет!»");GameIO.action(1,"Кто там у тебя?");GameIO.action(2,"Спокойно. Я слышал кашель.");GameIO.action(3,"Если ты кого-то прячешь, мне плевать. Я не за этим пришёл.");GameIO.action(0,"Отойти");int a=SurvivalSystems.choice(sc);if(a==0)return true;if(a<1||a>3)continue;stage=1;GameIO.checkpoint();}
   if(stage==1){GameIO.storyMenu("Вера и Миша","Вера: «Мой сын. Доволен? Теперь можешь уйти».\n\nДжон: «Он болен?»\n\nВера: «Он упал с лестницы. Сильно повредил ногу».\n\nДжон: «Я могу посмотреть».\n\nВера: «Да? А ты врач?»\n\nДжон: «Нет».\n\nВера: «Ну охуенно. Ещё один специалист».\n\nИз-за шкафа слышится детский голос.\n\nМиша: «Мам, дай ему воды».\n\nВера закрывает глаза.\n\nВера: «Миша, я тебе сказала молчать».\n\nМиша: «Он же не похож на тех».\n\nВера: «Те тоже нормально разговаривали».\n\nПауза.\n\nДжон: «Кто такие „те“?»\n\nВера: «Двое мужиков. Пришли сюда три дня назад. Сначала предложили помощь. Потом забрали почти всю еду».\n\nДжон: «Почему ты осталась здесь?»\n\nВера: «Потому что у него нога, блядь, не работает! Куда я его потащу?»\n\nОна указывает на шкаф.\n\nВера: «Всё. Ты узнал достаточно. Теперь уходи».");GameIO.action(1,"Продолжить");GameIO.action(0,"Отойти");if(SurvivalSystems.choice(sc)!=1)return true;stage=2;GameIO.checkpoint();}
   if(stage==2){GameIO.storyMenu("Как поступить с Верой?","Женщина с ножом защищает сына. Его нога тяжело повреждена.");GameIO.action(1,"Предложить медицинскую помощь");GameIO.action(2,"Предложить обмен припасами");GameIO.action(3,"Не вмешиваться и уйти");GameIO.action(0,"Отойти и вернуться позже");int a=SurvivalSystems.choice(sc);if(a==0)return true;if(a==1){stage=3;GameIO.checkpoint();}else if(a==2){stage=4;GameIO.checkpoint();}else if(a==3){stage=6;note(w,"Джон ушёл, не вмешиваясь. Вера и Миша остались в школе.");ResidentialStories.pause("Уход", "Джон: «Ладно. Я не буду вмешиваться».\n\nВера: «И правильно».\n\nДжон уже подходит к выходу.\n\nМиша: «Мам, а вдруг он хороший?»\n\nВера: «Миш...»\n\nМиша: «Ну вдруг».\n\nВера ничего не отвечает.",sc);return true;}}
   if(stage==3){GameIO.storyMenu("Помочь Мише","Джон: «У меня есть медицинские припасы. Давай помогу ему».\n\nВера: «И сколько это будет стоить?»\n\nДжон: «Нисколько».\n\nВера: «Да не пизди. Бесплатно сейчас даже в морду не дают».\n\nДжон: «Можешь продолжать спорить, а можешь дать мне посмотреть на ногу».\n\nОна колеблется.\n\nМиша: «Мам, пусть посмотрит».\n\nВера опускает нож.\n\nВера: «Одно резкое движение, и я тебя зарежу. Понятно?»\n\nДжон: «Очень гостеприимно».");GameIO.action(1,"Осмотреть рану");GameIO.action(0,"Назад к разговору");if(SurvivalSystems.choice(sc)==0){stage=2;GameIO.checkpoint();continue;}if(treat(p,sc)){helped=true;stage=6;note(w,"Джон обработал травму Миши. Вера предложила ключи от подсобки; лечение не гарантирует выздоровления.");ResidentialStories.pause("После перевязки","Миша: «Ай...»\n\nДжон: «Потерпи немного».\n\nВера: «Осторожнее».\n\nДжон: «Я стараюсь».\n\nМиша: «Мам, он хуже тебя ругается».\n\nВера: «Тогда точно не врач».\n\nДжон заканчивает перевязку.\n\nВера: «И что теперь?»\n\nДжон: «Повязку придётся менять. Ногу нужно беречь. Если станет хуже, нужна помощь человека, который разбирается в этом лучше меня».\n\nВера: «То есть ты не знаешь, поправится он или нет?»\n\nДжон: «Не знаю».\n\nВера: «Спасибо хотя бы за то, что не врёшь».\n\nВера: «Это от подсобки в конце коридора. Там раньше хранили инструменты и какие-то коробки».\n\nДжон: «Почему сама не забрала?»\n\nВера: «Потому что Миша не может ходить. А я не собиралась оставлять его одного».\n\nДжон: «Спасибо».\n\nВера: «Нет, это тебе спасибо».\n\nМиша: «Дядя Джон!»\n\nДжон: «Что?»\n\nМиша: «Ты ведь вернёшься?»\n\nДжон смотрит на Веру.\n\nДжон: «Не знаю, малой».\n\nМиша: «Тогда удачи».\n\nДжон: «И тебе».",sc);giveKey(p);return true;}stage=2;GameIO.checkpoint();}
   if(stage==4){GameIO.storyMenu("Обмен", "Джон: «У меня есть еда. Можем обменяться».\n\nВера: «На что? На старые парты?»\n\nДжон: «Может, у тебя есть что-нибудь полезное».\n\nВера: «Ты серьёзно? У меня больной ребёнок, а ты решил тут рынок устроить?»");ItemInfo food=ResidentialStories.find(p,ResidentialStories::food);GameIO.action(1,"Предложить еду без обмена","Нужна еда в рюкзаке",food!=null&&!fed);GameIO.action(2,"Настоять на обмене");GameIO.action(0,"Уйти");int a=SurvivalSystems.choice(sc);if(a==0){stage=2;GameIO.checkpoint();return true;}if(a==1&&food!=null&&!fed){p.getInventory().remove(food);fed=true;stage=2;note(w,"Джон отдал еду Вере без обмена.");ResidentialStories.pause("Еда для Миши","Вера принимает еду. Она немного успокаивается, но по-прежнему оберегает сына.",sc);}else if(a==2){stage=5;GameIO.checkpoint();}}
   if(stage==5){GameIO.storyMenu("Вера закрывает проход","Вера: «Знаешь что? Пошёл нахуй отсюда. Я второй раз на это не поведусь».\n\nДжон: «Я же просто предложил».\n\nВера: «А первые двое тоже просто предлагали!»\n\nОна отказывается продолжать переговоры.");GameIO.action(1,"Отойти");GameIO.action(2,"Силой открыть шкаф","Вера попытается защитить Мишу");int a=SurvivalSystems.choice(sc);if(a!=2)return true;if(enemy==null)enemy=new VeraEnemy();stage=9;GameIO.checkpoint();}
   if(stage==9){boolean won=TacticalBattle.story(p,sc,random,List.of(enemy),"Школьный класс",List.of(),false,false,false,true);if(!won){if(p.isAlive()){stage=8;note(w,"После отступления Вера больше не доверяет Джону и закрыла проход.");}return false;}if(enemy.isAlive()){stage=8;note(w,"Вера остаётся рядом с Мишей и не доверяет Джону.");return true;}stage=7;note(w,"Вера погибла. Миша остался жив в школьной комнате.");ResidentialStories.pause("Миша","Миша: «Мам?..»\n\nПауза.\n\nМиша: «Мама, вставай...»\n\nЗатем:\n\nМиша: «Уходи. Пожалуйста».",sc);return true;}
  }
  return p.isAlive();
 }
 boolean treat(Fighter p,Scanner sc){while(GameIO.hasInput(sc)){Fighter child=child();ItemInfo medicine=ResidentialStories.find(p,MedicalItem::supports);ItemInfo bandage=ResidentialStories.find(p,i->MedicalItem.supports(i)&&(i.getName().toLowerCase(Locale.ROOT).contains("бинт")||i.getName().toLowerCase(Locale.ROOT).contains("повяз")));GameIO.menu("Нога Миши","Повязка пропиталась грязью. Нога сильно опухла. Мальчик с трудом переносит прикосновение.");GameIO.illustratedCard("Состояние Миши",child.injurySummary(),"body-npc:"+child.bodyDiagramData());GameIO.action(1,"Обработать рану",medicine==null?"Нет подходящего средства":"Использовать: "+medicine.getName(),medicine!=null);GameIO.action(2,"Наложить повязку",bandage==null?"Нет бинта или повязки":"Использовать: "+bandage.getName(),bandage!=null);GameIO.action(3,"Отложить помощь");GameIO.action(0,"Назад");int a=SurvivalSystems.choice(sc);if(a==0||a==3)return false;ItemInfo use=a==1?medicine:a==2?bandage:null;if(use!=null){child.treat(BodyPart.LEFT_LEG,use);p.getInventory().remove(use);GameIO.out().println("Использован предмет: "+use.getName()+". Травма остаётся и требует времени.");return true;}}return false;}
 void giveKey(Fighter p){if(keyTaken)return;if(p.addItem(new Tools(KEY,"Ключи от школьной подсобки.",1,0))){keyTaken=true;GameIO.checkpoint();}else GameIO.out().println("Нет места: связка ключей осталась в школьной комнате.");}
 void cabinet(Fighter p,WorldStories w,Scanner sc){while(GameIO.hasInput(sc)){if(helped&&!keyTaken)giveKey(p);boolean key=ResidentialStories.find(p,i->i.getName().equals(KEY))!=null;boolean lever=ResidentialStories.lever(p);GameIO.menu("Подсобка в конце коридора",cabinetOpen?"Дверь открыта.":"Дверь закрыта. Подойдёт связка ключей Веры или лом.");if(!cabinetOpen)GameIO.action(1,"Открыть подсобку",key?"Ключ Веры":"Нужен лом",key||lever);if(cabinetOpen)GameIO.action(2,"Обыскать коробки",cabinetLoot?"Уже обысканы":"Бытовые материалы и немного припасов",!cabinetLoot);GameIO.action(0,"Назад");int a=SurvivalSystems.choice(sc);if(a==0)return;if(a==1&&!cabinetOpen&&(key||lever)){cabinetOpen=true;w.advanceMinutes(10);GameIO.checkpoint();}if(a==2&&cabinetOpen&&!cabinetLoot){cabinetLoot=true;GameIO.checkpoint();SurvivalSystems.collect(p,List.of(Shop.createItem(42),Shop.createItem(16)),sc);}}}
}
final class VeraEnemy extends HostileSurvivor {
 private static final long serialVersionUID=1L;
 VeraEnemy(){super("Вера",new Weapons("Кухонный нож","Нож Веры",1,8,WeaponStyle.KNIFE),45,true);}
 @Override List<ItemInfo> claimLoot(){List<ItemInfo> loot=new ArrayList<>(super.claimLoot());if(!loot.isEmpty()){loot.add(new Tools(VeraStory.KEY,"Ключи от школьной подсобки.",1,0));loot.add(Shop.createItem(16));}return loot;}
}
